import{_ as t,c as o,o as i,ah as s}from"./chunks/framework.D0LKgEKT.js";const p=JSON.parse('{"title":"Different Of  license","description":"","frontmatter":{},"headers":[],"relativePath":"OpenSource-LIcense.md","filePath":"OpenSource-LIcense.md","lastUpdated":1762180052000}'),r={name:"OpenSource-LIcense.md"};function n(a,e,l,c,h,d){return i(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="different-of-license" tabindex="-1">Different Of license <a class="header-anchor" href="#different-of-license" aria-label="Permalink to “Different Of  license”">​</a></h1><p>The three core terms of the BSD3 license</p><h2 id="three-clause" tabindex="-1">Three Clause <a class="header-anchor" href="#three-clause" aria-label="Permalink to “Three   Clause”">​</a></h2><p>If you use or distribute code based on the BSD3 license in your software, you must comply with these conditions:</p><p>The BSD3-Clause License is a widely used open-source software license. It is a very lenient license, meaning that it imposes very few restrictions on the use, modification and distribution of the software.</p><p>Its name is derived from its origin: the &quot;Berkeley Software Distribution&quot; version of the University of California, Berkeley, which was an early variant of the Unix operating system.</p><p>The three core terms of the BSD3 license</p><p>As the name suggests, &quot;3-Clause&quot; refers to the fact that it contains three main clauses. If you use or distribute code based on the BSD3 license in your software, you must comply with these conditions:</p><ol><li>Retain the original copyright notice and terms</li></ol><p>In any source code or binary (compiled) form you distribute, the original copyright notice, the list of license terms, and the disclaimer below must be included.</p><ol start="2"><li>It is prohibited to use the contributor&#39;s name to endorse or promote derivative works</li></ol><p>This is the second clause and also the main difference from the older &quot;BSD 4-Clause License&quot;. It stipulates that without prior written permission, the name of the original author or contributor shall not be used to endorse or promote products derived from this software.</p><ol start="3"><li>Disclaimer</li></ol><p>This is a standard legal statement clearly stating that the software is provided &quot;as is&quot; without any form of warranty. If there are any problems with the software, the author or the copyright owner shall not be held responsible. Main Features of the BSD 3-Clause License</p><ol><li>Highly Permissive:</li></ol><p>Unlike copyleft licenses such as the GPL (General Public License), the BSD 3-Clause License does not require you to release modifications or derivative works based on the code as open source.</p><p>You can use code licensed under BSD 3 in proprietary (closed-source) software and commercial products without having to disclose your source code.</p><ol start="2"><li>Business-Friendly:</li></ol><p>Due to its permissive nature, many companies (e.g., Google, Microsoft, Apple) prefer using code under the BSD 3-Clause License in their internal projects and commercial products.</p><ol start="3"><li>Encourages Distribution and Reuse:</li></ol><p>Its low barrier allows developers to easily use and share code, thereby fostering rapid technological development and innovation.</p><p>Summary</p><p>In conclusion, the BSD 3-Clause License is a simple, flexible, and highly business-friendly open-source agreement. Its greatest advantage is that it allows users almost unrestricted use of the code, including integrating it into closed-source commercial software. The only &quot;cost&quot; is respecting the original authors&#39; rights (retaining the copyright notice and not using their names for promotion without permission). MIT license</p><h1 id="the-differences-between-bsd3-and-mit" tabindex="-1">The differences between BSD3 and MIT <a class="header-anchor" href="#the-differences-between-bsd3-and-mit" aria-label="Permalink to “The differences between BSD3 and MIT”">​</a></h1><p>1.MIT license</p><p>The MIT license is the simplest and least restrictive among all open source licenses. It has only one requirement:</p><p>The original copyright notice and MIT license text must be included in your software copy or important parts.</p><p>Besides this, you can do almost anything:</p><p>You can use, copy, modify, merge, publish, distribute, sublicense and sell the software.</p><p>You can use the code for private or commercial closed-source projects without making your source code public.</p><p>Why choose MIT?</p><p>Developers usually choose MIT because they hope their code can be disseminated and used to the greatest extent possible, whether it&#39;s for personal projects, internal company projects or commercial products, and they don&#39;t want to set any obstacles.</p><ol start="2"><li>BSD 3-Clause License</li></ol><p>The BSD 3-Clause license adds an extra clause on the basis of the MIT license. It has three requirements:</p><p>When redistributing the source code, the original copyright notice, license terms and disclaimer must be retained.</p><p>When redistributing binary formats (such as compiled programs), the above copyright notice, license terms and disclaimer must be copied in the documentation or other provided materials.</p><p>Without prior written permission, the name of the original author or contributor may not be used to endorse or promote derivative works.</p><p>This third point is the sole and most crucial difference from the MIT license. It is also known as the &quot;No Endorsement&quot; clause.</p>',38)])])}const m=t(r,[["render",n]]);export{p as __pageData,m as default};
